package palindrome

import (
	"errors"
	"fmt"
)

// Product holds a palindromic product along with every pair of factors
// within the given range that produces it.
type Product struct {
	Value          int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic products of two
// numbers within [fmin, fmax] (both inclusive), along with all factor
// pairs of each. It reports an error if fmin > fmax or if no palindromic
// products exist in the range.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, fmt.Errorf("fmin > fmax: %d > %d", fmin, fmax)
	}

	var min, max Product
	found := false

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if !isPalindrome(product) {
				continue
			}
			if !found {
				min = Product{product, [][2]int{{i, j}}}
				max = min
				found = true
				continue
			}
			if product > max.Value {
				max = Product{product, [][2]int{{i, j}}}
			} else if product == max.Value {
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
			if product < min.Value {
				min = Product{product, [][2]int{{i, j}}}
			} else if product == min.Value {
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
		}
	}

	if !found {
		return Product{}, Product{}, errors.New("no palindromes found")
	}
	return min, max, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
func isPalindrome(n int) bool {
	if n < 0 {
		return false
	}
	original := n
	reversed := 0
	for n > 0 {
		reversed = reversed*10 + n%10
		n /= 10
	}
	return reversed == original
}

